/** Words that only say something needs fixing ("who fixes air conditioning", "my phone is broken"). */
export const REPAIR_WORDS = new Set(['fix', 'fixes', 'fixed', 'fixing', 'repair', 'repairs', 'repaired', 'repairing', 'broken', 'broke']);
/** Phrases that say the same. On their own they mean a car ("broke down"); after a thing, that thing ("my ac broke down"). */
export const REPAIR_PHRASES = new Set(['broke down', 'broken down', 'wont start']);

/**
 * Filter phrases: understood as filters rather than search words.
 * `open` = must be open right now; `late` = open until 10 PM or later today; `day` = open on that
 * weekday; `today` = open at some time today (becomes `day`), so "open today" never means this minute.
 */
export const FILTER_PHRASES = [
  { p: ['open now', 'open right now', 'currently open', 'open at the moment', 'still open', 'open'], f: { open: true } },
  { p: ['open today', 'opens today', 'open later today'], f: { today: true } },
  { p: ['open late', 'late night', 'late-night', 'open after 10', 'open after 10pm', 'after midnight', 'midnight'], f: { late: true } },
  { p: ['open sunday', 'open on sunday', 'open sundays', 'sunday'], f: { day: 6 } },
  { p: ['open saturday', 'open on saturday', 'open saturdays', 'saturday'], f: { day: 5 } },
  { p: ['open monday', 'open on monday', 'monday'], f: { day: 0 } },
];

/** After these, "open" means something is stuck ("the garage door won't open"), not "open now". */
export const NOT_WORDS = new Set(['not', 'dont', 'doesnt', 'didnt', 'isnt', 'cant', 'cannot', 'wont', 'wouldnt']);

