// Where it hurts, and who helps: "my back hurts", "bad knee", "pain in my lower back".
// Without these, a body part on its own gets "corrected" to a nearby word (back -> bank).
const ACHES = [
  [['Back & neck pain'], ['back', 'lower back', 'upper back', 'neck', 'spine']],
  [['Bone & joint doctors'], ['knee', 'hip', 'shoulder', 'elbow', 'wrist', 'ankle', 'joint', 'joints', 'hand', 'leg', 'arm']],
  [['Foot doctors (podiatry)'], ['foot', 'feet', 'heel', 'toe', 'toes']],
  [['Dentists'], ['tooth', 'teeth', 'gum', 'gums', 'jaw', 'mouth']],
  [['Hearing care'], ['ear', 'ears']],
  [['Eye care & glasses'], ['eye', 'eyes']],
  [['Heart doctors (cardiology)', 'Doctors'], ['chest']],
];
const ACHE_AFTER = ['hurts', 'pain', 'ache', 'aching', 'injury', 'problems', 'is sore', 'is hurting', 'is killing me'];
const ACHE_BEFORE = ['sore', 'bad', 'stiff', 'broken', 'hurt my', 'pulled my', 'injured my', 'broke my', 'pain in my'];
// Kept out of `p`, so typing "pul" or "bad" isn't offered "pulled my ear" or "bad toe".
for (const [labels, parts] of ACHES) {
  for (const it of labels.map(label => INTENTS.find(x => x.label === label))) {
    it.a = it.a || [];
    for (const part of parts) {
      // "My knee hurts" already works when "knee" is a phrase, and keeps "knee" as the typed word.
      const fillerOnly = w => it.p.includes(part) && w.split(' ').every(x => STOPWORDS.has(x));
      it.a.push(...ACHE_AFTER.filter(w => !fillerOnly(w)).map(w => `${part} ${w}`));
      it.a.push(...ACHE_BEFORE.filter(w => !fillerOnly(w)).map(w => `${w} ${part}`));
    }
  }
}
INTENTS.find(it => it.label === 'Hearing care').p.push('earache', 'earaches', 'ear infection');
